#include <iostream>
#include <string>
#include <vector>
#include <iomanip>

// Mô phỏng cấu trúc Record (Bản ghi) trong C++17
struct EmployeeRecord {
    int id;
    std::string name;
    double hourlyRate;
    double ytdEarnings;
};

int main() {
    // Bảng dữ liệu gồm danh sách các bản ghi (Records Table)
    std::vector<EmployeeRecord> payrollTable = {
        {101, "Alice", 35.50, 42600.00},
        {102, "Bob", 28.75, 34500.00}
    };

    std::cout << std::left << std::setw(6) << "ID"
              << std::setw(10) << "Name"
              << std::setw(12) << "Rate($/h)"
              << "YTD($)" << "\n";
    std::cout << "------------------------------------\n";

    for (const auto& emp : payrollTable) {
        std::cout << std::left << std::setw(6) << emp.id
                  << std::setw(10) << emp.name
                  << std::fixed << std::setprecision(2)
                  << std::setw(12) << emp.hourlyRate
                  << emp.ytdEarnings << "\n";
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <numeric>

// Minh họa triết lý Software Reuse: sử dụng container và thuật toán từ C++ Standard Library
int main() {
    // Sử dụng std::vector thay vì mảng cấp phát bộ nhớ thủ công
    std::vector<int> scores = {88, 95, 72, 91, 84};

    // Tái sử dụng thuật toán sắp xếp tối ưu từ <algorithm>
    std::sort(scores.begin(), scores.end());

    // Tái sử dụng thuật toán tính tổng tích lũy từ <numeric>
    int total = std::accumulate(scores.begin(), scores.end(), 0);
    double average = static_cast<double>(total) / scores.size();

    std::cout << "Sorted scores:";
    for (int s : scores) {
        std::cout << " " << s;
    }
    std::cout << "\nAverage score: " << average << "\n";

    return 0;
}

#include <iostream>
#include <string>
#include <vector>
#include <iomanip>

struct LanguageInfo {
    std::string name;
    std::string decade;
    std::string primaryRole;
};

int main() {
    std::vector<LanguageInfo> catalog = {
        {"Fortran",     "1950s", "Scientific & engineering computation"},
        {"COBOL",       "1950s", "Commercial and business data manipulation"},
        {"Basic",       "1960s", "Teaching novices programming techniques"},
        {"Pascal",      "1971",  "Structured programming instruction"},
        {"C",           "1972",  "UNIX OS development & systems programming"},
        {"Ada",         "1970s", "US Department of Defense mission systems"},
        {"Objective-C", "1980s", "Apple OS X and iOS device applications"}
    };

    std::cout << std::left << std::setw(14) << "Language"
              << std::setw(10) << "Era"
              << "Primary Domain" << "\n";
    std::cout << "------------------------------------------------------------\n";

    for (const auto& lang : catalog) {
        std::cout << std::left << std::setw(14) << lang.name
                  << std::setw(10) << lang.decade
                  << lang.primaryRole << "\n";
    }

    return 0;
}
